{"content":"/* Twinthos editorial preview v1 — one evolving composition.
   Palette and type inherit the live brand: ink #060807, paper #0E1210, ivory #ECEDE8, emerald #34D399. */

:root{
  --ink:#060807;
  --paper:#0E1210;
  --ivory:#ECEDE8;
  --muted:#9AA39D;
  --faint:#6C756F;
  --green:#34D399;
  --green-deep:#0F3B2C;
  --line:rgba(236,237,232,.13);
  --sans:"Inter Tight",ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;
  --mono:"Geist Mono",ui-monospace,SFMono-Regular,Menlo,monospace;
  --serif:"IBM Plex Serif",Georgia,serif;
  --nav:68px;
  --gut:clamp(20px,4.4vw,60px);
  --max:1180px;
  --ease:cubic-bezier(.22,.75,.2,1);
}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
html,body{margin:0;background:var(--ink);color:var(--ivory)}
body{
  font-family:var(--sans);
  font-size:clamp(15px,1.05vw,17px);
  line-height:1.6;
  -webkit-font-smoothing:antialiased;
  overflow-x:hidden;
}
img,svg{display:block;max-width:100%}
a{color:inherit;text-decoration:none}
h1,h2,h3,p,ul,dl,figure{margin:0}
ul{padding:0;list-style:none}

/* ---------- stage ---------- */
#stage{
  position:fixed;inset:0;z-index:0;pointer-events:none;
  background:
    radial-gradient(120% 90% at 50% 0%, #0B1512 0%, #070B09 48%, var(--ink) 100%);
}
#gl{width:100%;height:100%;display:block;opacity:0;transition:opacity 1.1s var(--ease)}
#gl.on{opacity:1}
#stage .fallback{position:absolute;inset:0;display:none}
body.no-gl #stage .fallback{display:block}
#stage .fallback svg{width:100%;height:100%;opacity:.5}

/* vignette + grain, kept quiet */
.vig{position:fixed;inset:0;z-index:1;pointer-events:none;
  background:radial-gradient(120% 100% at 50% 45%,transparent 40%,rgba(3,5,4,.55) 100%)}

/* ---------- shell ---------- */
.wrap{position:relative;z-index:2}
.pad{width:100%;max-width:var(--max);margin:0 auto;padding:0 var(--gut)}

.nav{
  position:fixed;top:0;left:0;right:0;height:var(--nav);z-index:20;
  display:flex;align-items:center;gap:28px;padding:0 var(--gut);
  background:linear-gradient(180deg,rgba(6,8,7,.92),rgba(6,8,7,.4) 70%,transparent);
  backdrop-filter:blur(6px);
}
.brand{display:flex;align-items:center;gap:10px;font-weight:600;letter-spacing:-.02em;font-size:17px}
.brand svg{width:21px;height:21px;fill:var(--ivory)}
.nav .links{display:flex;gap:22px;margin-left:auto;font-size:13.5px;color:var(--muted)}
.nav .links a:hover{color:var(--ivory)}
.nav .btn{margin-left:18px}
@media(max-width:820px){.nav .links{display:none}}

.btn{
  display:inline-flex;align-items:center;gap:10px;height:46px;padding:0 22px;
  border-radius:999px;background:var(--green);color:#04160E;font-weight:600;
  font-size:14.5px;letter-spacing:-.01em;transition:transform .35s var(--ease),background .3s;
}
.btn:hover{transform:translateY(-1px);background:#45E5AB}
.btn.ghost{background:transparent;color:var(--ivory);border:1px solid var(--line)}
.btn.ghost:hover{border-color:rgba(236,237,232,.34);background:rgba(236,237,232,.04)}
.btn svg{width:13px;height:13px;fill:none;stroke:currentColor;stroke-width:1.6}

/* ---------- shared editorial bits ---------- */
.kicker{
  font-family:var(--mono);font-size:11.5px;letter-spacing:.16em;text-transform:uppercase;
  color:var(--green);display:flex;align-items:center;gap:10px;
}
.kicker::before{content:"";width:22px;height:1px;background:currentColor;opacity:.6}
.lede{font-size:clamp(17px,1.5vw,21px);line-height:1.5;color:#C9CFC9;max-width:56ch}
.serif{font-family:var(--serif);font-style:italic;font-weight:400;letter-spacing:-.01em}

/* quiet scrim so type never sits on moving light */
.scrim{position:relative;isolation:isolate}
.scrim::before{
  content:"";position:absolute;inset:-8% -6%;z-index:-1;pointer-events:none;
  background:radial-gradient(75% 70% at 32% 50%,rgba(6,8,7,.94) 0%,rgba(6,8,7,.86) 45%,rgba(6,8,7,0) 78%);
}
.scrim.right::before{background:radial-gradient(75% 70% at 68% 50%,rgba(6,8,7,.94) 0%,rgba(6,8,7,.86) 45%,rgba(6,8,7,0) 78%)}

section.act{position:relative;padding:clamp(90px,13vh,150px) 0}
.act-num{font-family:var(--mono);font-size:11px;color:var(--faint);letter-spacing:.18em}

/* ---------- hero ---------- */
.hero{
  min-height:100svh;display:flex;align-items:flex-end;
  padding:calc(var(--nav) + 40px) 0 clamp(40px,7vh,76px);
}
.hero .pad{width:100%}
.hero .status{
  display:inline-flex;align-items:center;gap:9px;font-family:var(--mono);font-size:11.5px;
  letter-spacing:.14em;text-transform:uppercase;color:var(--muted);margin-bottom:26px;
}
.hero .dot{width:6px;height:6px;border-radius:50%;background:var(--green);box-shadow:0 0 12px var(--green)}
.hero h1{
  font-size:clamp(40px,7.1vw,104px);line-height:.96;letter-spacing:-.045em;font-weight:600;
  max-width:15ch;
}
.hero h1 em{font-family:var(--serif);font-style:italic;font-weight:400;letter-spacing:-.02em}
.hero .lede{margin-top:clamp(20px,3vh,32px);max-width:52ch}
.hero .ctas{display:flex;flex-wrap:wrap;gap:12px 22px;align-items:center;margin-top:clamp(24px,4vh,38px)}
.hero .price-line{
  margin-top:clamp(22px,3.4vh,34px);font-family:var(--mono);font-size:12px;letter-spacing:.06em;
  color:var(--faint);display:flex;gap:18px;flex-wrap:wrap;
}
.hero .price-line b{color:var(--muted);font-weight:400}

/* ---------- acts ---------- */
.act h2{
  font-size:clamp(30px,4.3vw,60px);line-height:1.02;letter-spacing:-.04em;font-weight:600;
  max-width:18ch;margin-top:18px;
}
.act h2 em{font-family:var(--serif);font-style:italic;font-weight:400}
.act .lede{margin-top:22px}
.split{display:grid;grid-template-columns:1.05fr .95fr;gap:clamp(32px,6vw,80px);align-items:start}
@media(max-width:900px){.split{grid-template-columns:1fr}}

.notes{margin-top:34px;display:grid;gap:1px;background:var(--line);border-top:1px solid var(--line)}
.notes li{background:var(--ink);padding:16px 2px;display:grid;grid-template-columns:28px 1fr;gap:14px;font-size:14.5px;color:#C3C9C3}
.notes li span{font-family:var(--mono);font-size:11px;color:var(--green);padding-top:3px}

/* cards on the right of an act */
.panel{
  border:1px solid var(--line);border-radius:16px;background:rgba(14,18,16,.66);
  backdrop-filter:blur(9px);padding:clamp(20px,2.6vw,30px);
}
.panel h3{font-size:12px;font-family:var(--mono);letter-spacing:.14em;text-transform:uppercase;color:var(--muted);font-weight:400}
.rowlist{margin-top:18px;display:grid;gap:12px}
.rowlist div{display:grid;grid-template-columns:auto 1fr;gap:14px;align-items:baseline;font-size:14.5px}
.rowlist b{font-weight:500;color:var(--ivory)}
.rowlist i{font-style:normal;color:var(--faint);font-family:var(--mono);font-size:11.5px;letter-spacing:.04em}
.tag{display:inline-flex;align-items:center;gap:7px;font-family:var(--mono);font-size:10.5px;letter-spacing:.1em;text-transform:uppercase;color:var(--green)}
.tag::before{content:"";width:5px;height:5px;border-radius:50%;background:currentColor}

/* knowledge items */
.k-items{display:grid;gap:10px;margin-top:26px}
.k-item{
  display:grid;grid-template-columns:1fr auto;gap:10px;align-items:center;
  padding:14px 16px;border:1px solid var(--line);border-radius:12px;background:rgba(14,18,16,.6);
  font-size:14px;
}
.k-item small{display:block;font-family:var(--mono);font-size:10.5px;color:var(--faint);letter-spacing:.08em;margin-top:4px}
.k-item em{font-style:normal;font-family:var(--mono);font-size:10.5px;color:var(--green);letter-spacing:.08em}

/* task strip — one request, tracked */
.request{
  border:1px solid var(--line);border-radius:16px;background:rgba(14,18,16,.72);
  padding:18px 20px;display:grid;gap:14px;
}
.request .id{display:flex;justify-content:space-between;font-family:var(--mono);font-size:10.5px;letter-spacing:.1em;color:var(--faint)}
.request .what{font-size:16px;letter-spacing:-.01em}
.steps{display:grid;gap:8px;margin-top:4px}
.steps li{display:grid;grid-template-columns:14px 1fr auto;gap:12px;align-items:center;font-size:13px;color:#B9C0B9;padding:7px 0;border-top:1px solid rgba(236,237,232,.07)}
.steps li:first-child{border-top:0}
.steps .b{width:8px;height:8px;border-radius:50%;border:1px solid var(--faint)}
.steps li.done .b{background:var(--green);border-color:var(--green)}
.steps li.wait .b{border-color:var(--green);background:transparent;box-shadow:0 0 0 3px rgba(52,211,153,.12)}
.steps .s{font-family:var(--mono);font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:var(--faint)}
.steps li.done .s{color:var(--green)}

/* timeline / persistence */
.timeline{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:30px}
@media(max-width:720px){.timeline{grid-template-columns:1fr}}
.tl-card{border:1px solid var(--line);border-radius:14px;padding:18px;background:rgba(14,18,16,.6)}
.tl-card .when{font-family:var(--mono);font-size:10.5px;letter-spacing:.12em;text-transform:uppercase;color:var(--faint)}
.tl-card p{margin-top:10px;font-size:14.5px;color:#C6CCC6}
.tl-card.now{border-color:rgba(52,211,153,.4)}
.tl-card.now .when{color:var(--green)}

/* boundary diagram */
.boundary{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--line);border:1px solid var(--line);border-radius:16px;overflow:hidden;margin-top:30px}
.boundary>div{background:rgba(14,18,16,.72);padding:20px}
.boundary h3{font-family:var(--mono);font-size:10.5px;letter-spacing:.12em;text-transform:uppercase;color:var(--green);font-weight:400}
.boundary ul{margin-top:12px;display:grid;gap:9px;font-size:14px;color:#C3C9C3}
@media(max-width:720px){.boundary{grid-template-columns:1fr}}

/* receipt */
.receipt{
  border:1px solid var(--line);border-radius:16px;background:rgba(10,13,11,.86);
  padding:clamp(20px,3vw,34px);margin-top:30px;
}
.receipt header{display:flex;justify-content:space-between;align-items:baseline;gap:16px;padding-bottom:14px;border-bottom:1px solid var(--line);flex-wrap:wrap}
.receipt h3{font-size:15px;font-weight:600;letter-spacing:-.01em}
.receipt header span{font-family:var(--mono);font-size:10.5px;letter-spacing:.1em;color:var(--faint);text-transform:uppercase}
.receipt dl{display:grid;gap:0;margin-top:6px}
.receipt dl>div{display:grid;grid-template-columns:150px 1fr;gap:18px;padding:13px 0;border-bottom:1px solid rgba(236,237,232,.07);font-size:14px}
.receipt dl>div:last-child{border-bottom:0}
.receipt dt{font-family:var(--mono);font-size:10.5px;letter-spacing:.1em;text-transform:uppercase;color:var(--faint);padding-top:4px}
.receipt dd{color:#C9CFC9}
.receipt .sig{margin-top:16px;font-family:var(--mono);font-size:10.5px;color:var(--faint);letter-spacing:.06em}
@media(max-width:620px){.receipt dl>div{grid-template-columns:1fr;gap:6px}}

/* pricing */
.price-grid{display:grid;grid-template-columns:1fr 1fr;gap:clamp(16px,2.4vw,28px);margin-top:44px}
@media(max-width:820px){.price-grid{grid-template-columns:1fr}}
.plan{border:1px solid var(--line);border-radius:18px;padding:clamp(22px,3vw,34px);background:rgba(10,13,11,.8);display:flex;flex-direction:column}
.plan.live{border-color:rgba(52,211,153,.34);background:linear-gradient(180deg,rgba(15,59,44,.28),rgba(10,13,11,.85))}
.plan .kind{font-family:var(--mono);font-size:10.5px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}
.plan .cost{font-size:clamp(34px,4.4vw,52px);letter-spacing:-.045em;font-weight:600;margin-top:14px;line-height:1}
.plan .cost small{font-size:14px;font-weight:400;letter-spacing:0;color:var(--muted);margin-left:6px}
.plan p{margin-top:16px;color:#BFC5BF;font-size:14.5px}
.plan ul{margin-top:20px;display:grid;gap:10px;font-size:13.8px;color:#C6CCC6}
.plan ul li{display:grid;grid-template-columns:14px 1fr;gap:10px}
.plan ul li::before{content:"";width:6px;height:6px;margin-top:8px;border-radius:50%;background:var(--green);opacity:.8}
.plan .btn{margin-top:auto;align-self:flex-start}
.plan .foot{margin-top:22px;font-family:var(--mono);font-size:10.5px;color:var(--faint);letter-spacing:.04em;line-height:1.7}

/* final */
.close{min-height:92svh;display:flex;align-items:center;padding:clamp(90px,12vh,150px) 0}
.close h2{font-size:clamp(42px,8vw,120px);line-height:.92;letter-spacing:-.05em;font-weight:600}
.close h2 em{font-family:var(--serif);font-style:italic;font-weight:400}
.close .ctas{display:flex;gap:14px;flex-wrap:wrap;margin-top:36px}
.close .meta{margin-top:40px;display:flex;gap:26px;flex-wrap:wrap;font-family:var(--mono);font-size:11px;color:var(--faint);letter-spacing:.08em}

/* footer */
footer{border-top:1px solid var(--line);padding:34px 0 46px;position:relative;z-index:2;background:rgba(6,8,7,.9)}
footer .pad{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;font-family:var(--mono);font-size:11px;color:var(--faint);letter-spacing:.06em}

/* controls */
.ctl{position:fixed;right:18px;bottom:18px;z-index:30;display:flex;gap:8px}
.ctl button{
  width:38px;height:38px;border-radius:50%;border:1px solid var(--line);background:rgba(10,13,11,.78);
  color:var(--muted);display:grid;place-items:center;cursor:pointer;backdrop-filter:blur(8px);
  transition:color .3s,border-color .3s,transform .3s
}
.ctl button:hover{color:var(--ivory);border-color:rgba(236,237,232,.3);transform:translateY(-1px)}
.ctl button:focus-visible{outline:2px solid var(--green);outline-offset:3px}
.ctl svg{width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}
.ctl .off{display:none}
.ctl button[aria-pressed="true"] .off{display:block}
.ctl button[aria-pressed="true"] .on{display:none}

/* progress rail */
.rail{position:fixed;left:0;top:0;width:2px;height:100%;z-index:25;background:rgba(236,237,232,.06)}
.rail i{display:block;width:100%;height:0;background:var(--green);transition:height .18s linear}
@media(max-width:640px){.rail{display:none}}

/* reduced motion: static composition */
body.reduced #stage #gl{display:none}
body.reduced #stage{background:
  radial-gradient(70% 55% at 50% 8%, rgba(52,211,153,.16), transparent 60%),
  radial-gradient(50% 40% at 82% 62%, rgba(52,211,153,.10), transparent 65%),
  radial-gradient(120% 90% at 50% 0%, #0B1512 0%, #070B09 55%, var(--ink) 100%);}
body.reduced .scrim::before{display:none}

/* print / no-js */
.no-js #gl{display:none}
