{"content":"/* Twinthos editorial preview — one evolving composition.
   A single WebGL point field carries ten compositions. Particle identity is stable:
   every point keeps its seed, so morphs travel rather than dissolve.
   Scroll selects a continuous phase; the opening runs as a timed prologue. */
(function (W, D) {
  'use strict';

  var stage = D.getElementById('stage');
  var cv = D.getElementById('gl');
  var rail = D.getElementById('railfill');
  var body = D.body;
  if (!stage || !cv) return;

  var reduce = W.matchMedia && W.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (reduce) { body.classList.add('reduced'); return; }

  var VERT = [
    'precision highp float;',
    'attribute vec4 aS;',
    'uniform float uT,uK,uPS,uDpr,uAl,uPortrait;',
    'uniform vec3 uFit;',
    'uniform vec2 uFr;',
    'uniform float uA,uB;',
    'varying vec4 vC;',
    'const float TAU=6.28318530718;',
    'const vec3 GR=vec3(0.204,0.827,0.600);',
    'const vec3 IV=vec3(0.925,0.929,0.910);',
    '',
    'vec2 markP(vec4 a,float K){',
    '  float pick=a.x*620.0; vec2 lo;',
    '  if(pick<158.0){ lo=vec2(mix(11.0,30.75,a.y),mix(12.0,20.0,a.z)); }',
    '  else if(pick<310.0){ lo=vec2(mix(26.0,30.75,a.y),mix(20.0,52.0,a.z)); }',
    '  else if(pick<468.0){ lo=vec2(mix(33.25,53.0,a.y),mix(12.0,20.0,a.z)); }',
    '  else { lo=vec2(mix(33.25,38.0,a.y),mix(20.0,52.0,a.z)); }',
    '  return (lo-vec2(32.0,32.0))*K;',
    '}',
    '',
    'vec2 shape(float sid, vec4 a, out vec3 col, out float al, out float sz){',
    '  int s=int(floor(sid+0.5));',
    '  col=GR; al=0.55; sz=1.0; vec2 p=vec2(0.0);',
    '  if(s==0){', /* dust */
    '    float r=340.0*sqrt(a.x)*(0.55+0.45*a.y);',
    '    float ang=a.z*TAU+sin(uT*0.22+a.x*6.0)*0.35;',
    '    p=vec2(cos(ang),sin(ang)*0.72)*r;',
    '    al=0.10+0.30*(1.0-a.x); sz=0.8;',
    '  } else if(s==1){', /* mark */
    '    p=markP(a,9.0); al=0.62+0.30*a.w; sz=1.05;',
    '  } else if(s==2){', /* hero: knowledge plane + work stream */
    '    if(a.x<0.45){',
    '      float i=floor(a.y*9.0),j=floor(a.z*7.0);',
    '      p=vec2(-560.0+i*(420.0/8.0),-260.0+j*(520.0/6.0));',
    '      p+=vec2((a.w-0.5)*5.0,(fract(a.x*97.0)-0.5)*5.0);',
    '      al=0.20+0.34*a.w; sz=0.85;',
    '    } else {',
    '      float t=(a.y-0.45)/0.55;',
    '      float x=120.0+t*480.0;',
    '      float y=sin(x*0.011+uT*0.65)*92.0+(a.z-0.5)*80.0;',
    '      p=vec2(x,y); col=mix(GR,IV,step(0.94,a.w));',
    '      al=0.28+0.5*a.w; sz=0.9+0.5*step(0.9,a.z);',
    '    }',
    '  } else if(s==3){', /* interrupted paths with gaps */
    '    float i=floor(a.y*4.0); float y=-270.0+i*180.0;',
    '    float x=mix(-680.0,680.0,a.x); float gc=-260.0+i*220.0;',
    '    if(abs(x-gc)<74.0){ x=gc+sign(x-gc)*(74.0+(a.z-0.5)*7.0); al=0.95; sz=1.2; col=mix(GR,IV,0.35); }',
    '    else { al=0.16+0.18*a.w; sz=0.8; }',
    '    p=vec2(x,y+(a.z-0.5)*4.0);',
    '  } else if(s==4){', /* knowledge planes */
    '    float sh=floor(a.x*4.0); float y=-250.0+sh*165.0;',
    '    float x=mix(-640.0,640.0,a.y)*(0.78+0.06*sh);',
    '    y+=26.0*sin(x*0.006);',
    '    p=vec2(x,y+(a.z-0.5)*5.0);',
